<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import {api,apiBaseUrl} from '../lib/api'
import {asset} from '../lib/assets'
const props=defineProps<{token:string;conversation:{id:string;displayName:string;remark?:string;status:string}}>()
const emit=defineEmits<{close:[];collect:[]}>()
type Message={id:string;content:string;kind:string;createdAt:string;senderId?:string;mine?:boolean;mediaId?:string;media?:{url:string;kind:string}[]}
const rows=ref<Message[]>([]),pending=ref(false),open=ref(props.conversation.status==='open'),draft=ref(sessionStorage.getItem('chat-draft-'+props.conversation.id)||''),screen=ref('chat'),query=ref(''),results=ref<Message[]>([]),searched=ref(false),remark=ref(props.conversation.remark||''),error=ref(''),busy=ref(false),stickers=ref(false),selected=ref(''),photo=ref<File>(),preview=ref(''),record=ref(''),micDenied=ref(false),sent=ref(false),cleared=ref(false),confirm=ref(false),editing=ref(false),more=ref(false)
const state=computed(()=>confirm.value?'chat-clear-confirm':editing.value?'chat-remark':screen.value==='details'?(open.value?'chat-details':'chat-details-waiting'):screen.value==='search'?(!query.value?'chat-search-empty':searched.value&&results.value.length?'chat-search-result':'chat-search-none'):record.value==='cancel'?'chat-record-cancel':record.value?'chat-recording':micDenied.value?'chat-mic-denied':!open.value?(pending.value?'chat-receipt-waiting':'chat-waiting'):photo.value?'chat-attachment':selected.value?'chat-sticker-selected':stickers.value?'chat-stickers':draft.value?'chat-draft':sent.value?'chat-sent':cleared.value?'chat-cleared':rows.value.some(m=>m.media?.length)?'chat-photo':'chat-open')
function request<T>(path:string,method='GET',body?:object){return api<T>(path,{method,headers:{Authorization:`Bearer ${props.token}`,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})})}
function fail(e:unknown){error.value=(e as Error).message}
const objectURLs:string[]=[]
async function load(append=false){try{const r=await request<{items:Message[];hasMore?:boolean}>(`/conversations/${props.conversation.id}/messages?markRead=true&limit=20&offset=${append?rows.value.length:0}`);for(const m of r.items){const path=m.mediaId?`/media/uploads/${m.mediaId}`:/^\/media\/uploads\/[0-9a-f-]+$/.test(m.content)?m.content:undefined;if(path){const response=await fetch(apiBaseUrl+path,{headers:{Authorization:`Bearer ${props.token}`}});if(!response.ok)throw Error('Unable to load photo.');const url=URL.createObjectURL(await response.blob());objectURLs.push(url);m.media=[{url,kind:response.headers.get('Content-Type')?.startsWith('audio/')?'audio':'image'}];m.content=''}}rows.value=append?[...rows.value,...r.items]:r.items;more.value=!!r.hasMore;const q=await request<{items:{id:string}[]}>(`/conversations/${props.conversation.id}/replies/pending`);pending.value=q.items.length>0}catch(e){fail(e)}}
function gate(){if(!open.value){error.value='Photos, voice and stickers unlock after they reply.';return false}return true}
async function send(){if(busy.value||!gate()||(!draft.value.trim()&&!photo.value&&!selected.value))return;busy.value=true;error.value='';try{let mediaId:string|undefined;const attachment=photo.value||(selected.value?new File([await (await fetch(asset('06-stickers/'+selected.value))).blob()],'sticker.png',{type:'image/png'}):undefined);if(attachment){const q=new URLSearchParams({purpose:'chat',conversationId:props.conversation.id,filename:'photo.'+(attachment.type==='image/png'?'png':attachment.type==='image/webp'?'webp':'jpg')});const upload=(path:string)=>api<{id:string}>(path,{method:'POST',headers:{Authorization:`Bearer ${props.token}`,'Content-Type':attachment.type},body:attachment});const r=await upload(`/media/uploads?${q}`);mediaId=r.id}const content=draft.value.trim();let r:{id:string};if(mediaId){r=await request<{id:string}>(`/conversations/${props.conversation.id}/media`,'POST',{mediaId});if(content)await request(`/conversations/${props.conversation.id}/messages`,'POST',{content})}else{r=await request<{id:string}>(`/conversations/${props.conversation.id}/messages`,'POST',{content})}rows.value.push({id:r.id,content,kind:'reply',mine:true,createdAt:new Date().toISOString(),...(attachment?{media:[{url:photo.value?preview.value:asset('06-stickers/'+selected.value),kind:'image'}]}:{})});draft.value='';selected.value='';photo.value=undefined;stickers.value=false;sent.value=true;cleared.value=false}catch(e){fail(e)}finally{busy.value=false}}
function choose(e:Event){if(!gate())return;const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>=10*1024*1024){error.value='Choose an image smaller than 10 MB.';return}photo.value=f;preview.value=URL.createObjectURL(f);objectURLs.push(preview.value)}
const voice=ref<Blob>(),voiceURL=ref(''),seconds=ref(0),voiceNotice=ref(''),uploadFailed=ref(false)
const voiceTime=computed(()=>`${Math.floor(seconds.value/60)}:${String(Math.floor(seconds.value%60)).padStart(2,'0')}`)
let startY=0,holding=false,generation=0,stream:MediaStream|undefined,context:AudioContext|undefined,source:MediaStreamAudioSourceNode|undefined,processor:ScriptProcessorNode|undefined,ticker:ReturnType<typeof setInterval>|undefined,started=0,sampleRate=44100,samples:Float32Array[]=[],peak=0,uploadedId:string|undefined
function cleanup(){clearInterval(ticker);processor?.disconnect();source?.disconnect();stream?.getTracks().forEach(t=>t.stop());void context?.close();processor=undefined;source=undefined;stream=undefined;context=undefined;samples=[]}
function discardVoice(){if(voiceURL.value)URL.revokeObjectURL(voiceURL.value);voiceURL.value='';voice.value=undefined;uploadedId=undefined;uploadFailed.value=false}
function cancelVoice(){holding=false;generation++;record.value='';cleanup();discardVoice();voiceNotice.value='Recording cancelled. No audio was sent.'}
function wav(chunks:Float32Array[],rate:number){const length=chunks.reduce((n,c)=>n+c.length,0),buffer=new ArrayBuffer(44+length*2),v=new DataView(buffer);const str=(o:number,t:string)=>{for(let i=0;i<t.length;i++)v.setUint8(o+i,t.charCodeAt(i))};str(0,'RIFF');v.setUint32(4,36+length*2,true);str(8,'WAVE');str(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,rate,true);v.setUint32(28,rate*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);str(36,'data');v.setUint32(40,length*2,true);let offset=44;for(const chunk of chunks)for(const sample of chunk){v.setInt16(offset,Math.max(-1,Math.min(1,sample))*32767,true);offset+=2}return new Blob([buffer],{type:'audio/wav'})}
async function hold(e:PointerEvent){if(!gate()||busy.value||record.value||voice.value)return;startY=e.clientY;holding=true;const version=++generation;micDenied.value=false;voiceNotice.value='';error.value='';record.value='requesting';(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('unavailable');const acquired=await navigator.mediaDevices.getUserMedia({audio:true});if(version!==generation||!holding){acquired.getTracks().forEach(t=>t.stop());return}stream=acquired;context=new AudioContext();await context.resume();if(version!==generation||!holding){cleanup();return}sampleRate=context.sampleRate;source=context.createMediaStreamSource(stream);processor=context.createScriptProcessor(4096,1,1);samples=[];peak=0;processor.onaudioprocess=event=>{const remaining=Math.max(0,Math.floor(sampleRate*60)-samples.reduce((n,c)=>n+c.length,0));const data=new Float32Array(event.inputBuffer.getChannelData(0).subarray(0,remaining));samples.push(data);for(const x of data)peak=Math.max(peak,Math.abs(x));seconds.value=samples.reduce((n,c)=>n+c.length,0)/sampleRate};source.connect(processor);processor.connect(context.destination);started=performance.now();seconds.value=0;if(record.value!=='cancel')record.value='recording';ticker=setInterval(()=>{if(performance.now()-started>=60000){voiceNotice.value='60 second limit reached. Preview your recording.';finishVoice()}},100)}catch(e){if(version!==generation)return;holding=false;record.value='';cleanup();micDenied.value=true;const name=(e as Error).name;voiceNotice.value=name==='NotAllowedError'||name==='SecurityError'?'Microphone permission denied. Allow microphone access in browser settings and try again.':`Microphone unavailable. Connect a microphone and try again. (${(e as Error).name}: ${(e as Error).message})`}}
function move(e:PointerEvent){if(holding&&record.value)record.value=startY-e.clientY>65?'cancel':processor?'recording':'requesting'}
function finishVoice(){if(record.value==='cancel'){cancelVoice();return}holding=false;generation++;record.value='';const chunks=samples,level=peak;seconds.value=chunks.reduce((n,c)=>n+c.length,0)/sampleRate;cleanup();if(seconds.value<0.5||level<0.008){voiceNotice.value='Recording too short or no sound detected. Please record again.';return}voice.value=wav(chunks,sampleRate);voiceURL.value=URL.createObjectURL(voice.value)}
function release(){if(holding)finishVoice()}
async function sendVoice(){if(!voice.value||busy.value||!gate())return;busy.value=true;uploadFailed.value=false;voiceNotice.value='';try{if(!navigator.onLine)throw Error('You are offline. Reconnect and retry.');if(!uploadedId){const q=new URLSearchParams({purpose:'chat',conversationId:props.conversation.id,filename:'voice.wav'});uploadedId=(await api<{id:string}>(`/media/uploads?${q}`,{method:'POST',headers:{Authorization:`Bearer ${props.token}`,'Content-Type':'audio/wav'},body:voice.value})).id}const result=await request<{id:string}>(`/conversations/${props.conversation.id}/media`,'POST',{mediaId:uploadedId});objectURLs.push(voiceURL.value);rows.value.push({id:result.id,kind:'audio',content:'',mine:true,createdAt:new Date().toISOString(),media:[{url:voiceURL.value,kind:'audio'}]});voice.value=undefined;voiceURL.value='';uploadedId=undefined;sent.value=true;voiceNotice.value='Voice message sent.'}catch(e){uploadFailed.value=true;voiceNotice.value=`Voice upload/send failed. ${(e as Error).message} Your recording is available to retry.`}finally{busy.value=false}}
function leaveVoice(){if(record.value)cancelVoice()}
function visibilityChange(){if(document.hidden)leaveVoice()}
watch(screen,leaveVoice)
async function patch(body:object){if(busy.value)return;busy.value=true;error.value='';try{await request(`/conversations/${props.conversation.id}`,'PATCH',body);if('clearHistory' in body){rows.value=[];cleared.value=true;sent.value=false;micDenied.value=false;confirm.value=false;screen.value='chat'}else{editing.value=false;props.conversation.remark=remark.value}}catch(e){fail(e)}finally{busy.value=false}}
let searchVersion=0,timer:ReturnType<typeof setTimeout>,poll:ReturnType<typeof setInterval>
watch(query,()=>{clearTimeout(timer);searched.value=false;const version=++searchVersion;results.value=[];if(!query.value.trim())return;timer=setTimeout(async()=>{try{const r=await request<{items:Message[]}>(`/conversations/${props.conversation.id}/messages?markRead=false&limit=50&offset=0&search=${encodeURIComponent(query.value.trim())}`);if(version===searchVersion){results.value=r.items;searched.value=true}}catch(e){if(version===searchVersion)fail(e)}},250)})
watch(draft,v=>sessionStorage.setItem('chat-draft-'+props.conversation.id,v))
function back(){if(record.value)cancelVoice();if(voice.value&&!busy.value)discardVoice();if(confirm.value)confirm.value=false;else if(editing.value)editing.value=false;else if(screen.value!=='chat')screen.value='chat';else emit('close')}
onMounted(()=>{document.addEventListener('visibilitychange',visibilityChange);void load();poll=setInterval(()=>{if(!open.value)void load()},4000)})
onUnmounted(()=>{document.removeEventListener('visibilitychange',visibilityChange);generation++;holding=false;cleanup();discardVoice();clearInterval(poll);clearTimeout(timer);searchVersion++;objectURLs.forEach(url=>URL.revokeObjectURL(url))})
</script>
<template>
<section class="c6-chat" :data-state="state"><header><button aria-label="Back to messages" @click="back">‹</button><h1>{{screen==='details'?'Chat details':screen==='search'?'Search messages':conversation.remark||conversation.displayName}}</h1><button id="chat-details" aria-label="Chat details" @click="screen='details'">•••</button></header>
<p v-if="error" role="alert" class="c6-error">{{error}} <button @click="error='';load()">Retry</button></p>
<template v-if="screen==='chat'"><p class="chat-notice">Be kind. Every little story matters.</p><div id="chat-thread" class="c6-thread"><button v-if="more" @click="load(true)">Earlier messages</button><TransitionGroup name="c6-message"><article v-for="m in rows" :key="m.id" class="chat-message" :class="{mine:m.mine}"><img v-if="!m.mine" :src="asset('05-avatars/avatar-placeholder')" alt=""><div class="chat-bubble"><span>{{m.content}}</span><template v-for="media in m.media" :key="media.url"><audio v-if="media.kind==='audio'" :src="media.url" controls preload="metadata" aria-label="Voice message"></audio><img v-else :src="media.url" alt="Photo message"></template></div><small>{{new Date(m.createdAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}}</small></article></TransitionGroup><p v-if="!rows.length" class="c6-empty">{{cleared?'Chat history cleared. Your connection stays open.':'No messages yet.'}}</p></div>
<Transition name="c6-panel"><div v-if="!open" class="waiting-card"><strong>{{pending?'A reply has arrived.':'Waiting for their reply'}}</strong><p>{{pending?'Collect your reply from Inbox to continue.':'Your one opening message is sent. More messages and interactions unlock after they reply.'}}</p><button v-if="pending" @click="emit('collect')">Collect your reply</button></div></Transition>
<form v-if="open" id="chat-form" class="c6-composer" @submit.prevent="send"><div v-if="photo||selected" class="c6-attachment"><img :src="photo?preview:asset('06-stickers/'+selected)" alt="Pending attachment"><button type="button" aria-label="Remove attachment" @click="photo=undefined;selected=''">×</button></div><div class="c6-input"><input id="chat-input" v-model="draft" maxlength="200" aria-label="Message" placeholder="Say something kind…"><button id="chat-send" aria-label="Send message" :disabled="busy||(!draft.trim()&&!photo&&!selected)">{{busy?'…':'➤'}}</button></div><div class="chat-tools"><button id="chat-stickers" type="button" aria-label="Stickers" @click="gate()&&(stickers=!stickers)">☻</button><label class="c6-photo" aria-label="Photo">▧<input id="chat-photo" type="file" accept="image/png,image/jpeg,image/webp" aria-label="Photo" @change="choose"></label><button id="chat-hold" type="button" @pointerdown.prevent="hold" @pointermove="move" @pointerup="release" @pointercancel="cancelVoice" :disabled="busy||!!voice">♩ Hold to talk</button></div><Transition name="c6-panel"><div v-if="stickers" class="c6-stickers"><button v-for="s in ['sticker-5-711','sticker-5-316','sticker-5-626','sticker-5-727']" :key="s" type="button" class="sticker-option" :aria-label="s" @click="gate()&&(selected=s)"><img :src="asset('06-stickers/'+s)" alt="Sticker"></button></div></Transition></form>
<Transition name="c6-panel"><div v-if="record" class="c6-record" :class="{cancel:record==='cancel'}" role="status"><div class="c6-wave">▂ ▆ ▃ █ ▄ ▆ ▂</div><strong>{{record==='cancel'?'Release to cancel':'Slide up to cancel'}}</strong><p>{{record==='requesting'?'Requesting microphone…':voiceTime+' / 1:00'}}</p></div></Transition><Transition name="c6-panel"><div v-if="voice" class="c6-voice-preview"><strong>Preview voice · {{voiceTime}}</strong><audio :src="voiceURL" controls aria-label="Preview voice"></audio><div><button type="button" :disabled="busy" @click="discardVoice();voiceNotice='Record again when ready.'">Re-record</button><button type="button" :disabled="busy" @click="discardVoice();voiceNotice='Recording cancelled. No audio was sent.'">Cancel</button><button id="voice-send" type="button" :disabled="busy" @click="sendVoice">{{busy?'Sending…':uploadFailed?'Retry voice':'Send voice'}}</button></div></div></Transition><p v-if="voiceNotice" class="c6-voice-notice" role="status">{{voiceNotice}}</p></template>
<template v-else-if="screen==='details'"><div class="c6-person"><img :src="asset('05-avatars/avatar-placeholder')" alt=""><h2>{{conversation.remark||conversation.displayName}}</h2><p>{{open?'You can now chat freely.':'More interactions unlock after they reply.'}}</p></div><button id="remark-name" class="c6-row" @click="editing=true">Remark name <span>{{remark||'Set a remark'}} ›</span></button><button class="c6-row" @click="screen='search'">Search chat history <span>›</span></button><button id="clear-chat" class="c6-row" @click="confirm=true">Clear chat history <span>›</span></button></template>
<template v-else><input id="message-search" v-model="query" class="c6-search" aria-label="Search messages" placeholder="Search messages"><div class="c6-results"><p v-if="!query">Search for a word in your conversation.</p><p v-else-if="!searched">Searching…</p><p v-else-if="!results.length">No messages found.</p><article v-for="m in results" :key="m.id"><p>{{m.content}}</p><small>{{new Date(m.createdAt).toLocaleString()}}</small></article></div></template>
<Transition name="c6-panel"><div v-if="confirm||editing" class="c6-veil" @click.self="!busy&&(confirm=false,editing=false)"><section role="dialog" aria-modal="true" :aria-label="confirm?'Clear chat history?':'Remark name'"><h2>{{confirm?'Clear chat history?':'Remark name'}}</h2><p v-if="confirm">This only clears your chat history. Your connection and unlocked permissions stay the same.</p><input v-else v-model="remark" maxlength="60" aria-label="Remark"><button class="primary" :disabled="busy" @click="confirm?patch({clearHistory:true}):patch({remark})">{{busy?'Saving…':confirm?'Clear history':'Save remark'}}</button><button :disabled="busy" @click="confirm=false;editing=false">Cancel</button></section></div></Transition></section>
</template>
<style src="../chat.css"></style>
